"""Independent cycle closure and sorted complete DAG words;actual category certificate."""

ORIGINAL = 'impl FinitePathCategory {\n    fn original_new(vertices: usize, edges: Vec<PathEdge>, max_paths: usize) -> Result<Self, PathError> {\n        if vertices == 0 {\n            return Err(PathError::EmptyGraph);\n        }\n        if vertices > MAX_PATHS || edges.len() > MAX_PATHS {\n            return Err(PathError::GraphBudget);\n        }\n        if edges\n            .iter()\n            .any(|e| e.source >= vertices || e.target >= vertices)\n        {\n            return Err(PathError::InvalidVertex);\n        }\n        let mut outgoing = vec![Vec::new(); vertices];\n        let mut indegree = vec![0usize; vertices];\n        for (i, e) in edges.iter().enumerate() {\n            outgoing[e.source].push(i);\n            indegree[e.target] += 1;\n        }\n        let mut ready: BTreeSet<_> = (0..vertices).filter(|&v| indegree[v] == 0).collect();\n        let mut visited = 0;\n        while let Some(v) = ready.pop_first() {\n            visited += 1;\n            for &i in &outgoing[v] {\n                let target = edges[i].target;\n                indegree[target] -= 1;\n                if indegree[target] == 0 {\n                    ready.insert(target);\n                }\n            }\n        }\n        if visited != vertices {\n            return Err(PathError::Cycle);\n        }\n        let budget = max_paths.min(MAX_PATHS);\n        if vertices > budget {\n            return Err(PathError::PathBudget);\n        }\n        // Identities have indices exactly equal to their vertices.\n        let mut paths: Vec<_> = (0..vertices)\n            .map(|v| FinitePath {\n                source: v,\n                target: v,\n                edges: vec![],\n            })\n            .collect();\n        let mut cursor = 0;\n        while cursor < paths.len() {\n            for &edge in &outgoing[paths[cursor].target] {\n                if paths.len() == budget {\n                    return Err(PathError::PathBudget);\n                }\n                let mut word = paths[cursor].edges.clone();\n                word.push(edge);\n                paths.push(FinitePath {\n                    source: paths[cursor].source,\n                    target: edges[edge].target,\n                    edges: word,\n                });\n            }\n            cursor += 1;\n        }\n        let indices: BTreeMap<_, _> = paths\n            .iter()\n            .enumerate()\n            .map(|(i, p)| ((p.source, p.edges.clone()), i))\n            .collect();\n        let mut category =\n            DeclaredFiniteCategory::new("complete finite acyclic free path category");\n        for v in 0..vertices {\n            category.add_identity(&format!("v{v}"), &format!("p{v}"));\n        }\n        for (i, p) in paths.iter().enumerate().skip(vertices) {\n            category.add_morphism(\n                &format!("p{i}"),\n                &format!("v{}", p.source),\n                &format!("v{}", p.target),\n            );\n        }\n        let mut composition = vec![vec![None; paths.len()]; paths.len()];\n        for (i, p) in paths.iter().enumerate() {\n            for (j, q) in paths.iter().enumerate() {\n                if p.target != q.source {\n                    continue;\n                }\n                let mut word = p.edges.clone();\n                word.extend_from_slice(&q.edges);\n                let k = *indices\n                    .get(&(p.source, word))\n                    .ok_or(PathError::MissingComposite)?;\n                composition[i][j] = Some(k);\n                category.set_composition(&format!("p{i}"), &format!("p{j}"), &format!("p{k}"));\n            }\n        }\n        let category = ValidatedFiniteCategory::try_new(category)\n            .map_err(|_| PathError::CategoryValidation)?;\n        Ok(Self {\n            vertices,\n            edges,\n            paths,\n            composition,\n            category,\n        })\n    }\n}\n'

TESTS = r'''
fn cyclic(n:usize,edges:&[PathEdge])->bool{let mut reach=vec![vec![false;n];n];for e in edges{reach[e.source][e.target]=true;}for k in 0..n{for i in 0..n{for j in 0..n{reach[i][j]|=reach[i][k]&&reach[k][j];}}}(0..n).any(|i|reach[i][i])}
fn oracle_paths(n:usize,edges:&[PathEdge])->Vec<FinitePath>{
 fn visit(start:usize,end:usize,word:&mut Vec<usize>,edges:&[PathEdge],out:&mut Vec<FinitePath>){out.push(FinitePath{source:start,target:end,edges:word.clone()});for (id,edge) in edges.iter().enumerate(){if edge.source==end{word.push(id);visit(start,edge.target,word,edges,out);word.pop();}}}
 let mut out=Vec::new();for start in 0..n{visit(start,start,&mut Vec::new(),edges,&mut out);}out.sort_by(|a,b|(a.edges.len(),a.source,&a.edges).cmp(&(b.edges.len(),b.source,&b.edges)));out
}
fn check(n:usize,edges:Vec<PathEdge>,budget:usize){
 let actual=FinitePathCategory::new(n,edges.clone(),budget);if cyclic(n,&edges){assert_eq!(actual,Err(PathError::Cycle));return;}let expected=oracle_paths(n,&edges);if expected.len()>budget.min(MAX_PATHS){assert_eq!(actual,Err(PathError::PathBudget));return;}let out=actual.unwrap();assert_eq!(out,FinitePathCategory::original_new(n,edges.clone(),budget).unwrap());assert_eq!(out.vertices(),n);assert_eq!(out.edges(),edges);assert_eq!(out.paths(),expected);let raw=out.category().declared();assert_eq!(raw.objects.len(),n);assert_eq!(raw.morphisms.len(),expected.len());assert_eq!(raw.name,"complete finite acyclic free path category");let mut counts=vec![0;n];
 for (i,p) in expected.iter().enumerate(){assert_eq!(out.path(i),Ok(p));assert_eq!(p.source(),p.source);assert_eq!(p.target(),p.target);assert_eq!(p.edges(),p.edges);counts[p.source]+=1;let name=format!("p{i}");assert_eq!(raw.boundary_of(&name),Some((format!("v{}",p.source).as_str(),format!("v{}",p.target).as_str())));for (j,q) in expected.iter().enumerate(){let composite=if p.target==q.source{let word:Vec<_>=p.edges.iter().chain(&q.edges).copied().collect();Some(expected.iter().position(|r|r.source==p.source&&r.edges==word).unwrap())}else{None};assert_eq!(out.compose(i,j),Ok(composite));let actual=raw.compose(&name,&format!("p{j}"));assert_eq!(actual,composite.map(|k|format!("p{k}")).as_deref());}}
 for vertex in 0..n{assert_eq!(out.path(vertex).unwrap().edges(),[] as [usize;0]);assert_eq!(raw.identity_of(&format!("v{vertex}")),Some(format!("p{vertex}").as_str()));}
 for (id,e) in edges.iter().enumerate(){let path=out.edge_path(id).unwrap();assert_eq!(out.path(path).unwrap(),&FinitePath{source:e.source,target:e.target,edges:vec![id]});}assert_eq!(out.edge_path(edges.len()),Err(PathError::UnknownPath));assert_eq!(out.path(expected.len()),Err(PathError::UnknownPath));assert_eq!(out.compose(expected.len(),0),Err(PathError::UnknownPath));assert_eq!(out.compose(0,usize::MAX),Err(PathError::UnknownPath));assert_eq!(out.origin_path_counts(),counts);
}
#[test]fn all_three_vertex_multigraphs_and_path_budget_boundaries(){
 let pairs:Vec<_>=(0..3).flat_map(|a|(0..3).filter(move|&b|a!=b).map(move|b|(a,b))).collect();let mut graphs=0;
 for code in 0..729{let mut n=code;let mut edges=Vec::new();for &(a,b) in &pairs{let count=n%3;n/=3;for _ in 0..count{edges.push(PathEdge{source:a,target:b});}}
  if cyclic(3,&edges){check(3,edges,0);}else{let count=oracle_paths(3,&edges).len();for budget in 0..=count+1{check(3,edges.clone(),budget);}edges.reverse();check(3,edges,64);}graphs+=1;
 }assert_eq!(graphs,729);
}
#[test]fn complete_four_vertex_dags_parallel_names_and_refusals(){
 let pairs:Vec<_>=(0..4).flat_map(|a|(a+1..4).map(move|b|(a,b))).collect();for mask in 0usize..64{let edges=pairs.iter().enumerate().filter_map(|(i,&(source,target))|(mask&(1<<i)!=0).then_some(PathEdge{source,target})).collect();check(4,edges,64);}
 check(1,Vec::new(),1);check(64,Vec::new(),64);assert_eq!(FinitePathCategory::new(0,vec![PathEdge{source:99,target:99};65],0),Err(PathError::EmptyGraph));assert_eq!(FinitePathCategory::new(65,Vec::new(),0),Err(PathError::GraphBudget));assert_eq!(FinitePathCategory::new(usize::MAX,Vec::new(),usize::MAX),Err(PathError::GraphBudget));assert_eq!(FinitePathCategory::new(1,vec![PathEdge{source:99,target:99};65],0),Err(PathError::GraphBudget));assert_eq!(FinitePathCategory::new(2,vec![PathEdge{source:2,target:0}],0),Err(PathError::InvalidVertex));assert_eq!(FinitePathCategory::new(2,vec![PathEdge{source:0,target:2}],0),Err(PathError::InvalidVertex));assert_eq!(FinitePathCategory::new(1,vec![PathEdge{source:0,target:0};64],0),Err(PathError::Cycle));assert_eq!(FinitePathCategory::new(2,vec![PathEdge{source:0,target:1};64],64),Err(PathError::PathBudget));
 let edges:Vec<_>=(0..5).flat_map(|source|[PathEdge{source,target:source+1};2]).collect();assert_eq!(FinitePathCategory::new(6,edges,usize::MAX),Err(PathError::PathBudget));
 for error in [PathError::EmptyGraph,PathError::GraphBudget,PathError::InvalidVertex,PathError::Cycle,PathError::PathBudget,PathError::UnknownPath,PathError::MissingComposite,PathError::CategoryValidation]{assert_eq!(error.to_string(),format!("finite path category refused: {error:?}"));}
}
#[test]fn borrowed_lookup_and_category_composition_are_not_just_counters(){
 let graph=vec![PathEdge{source:1,target:2},PathEdge{source:0,target:1},PathEdge{source:0,target:2},PathEdge{source:0,target:1}];check(3,graph.clone(),64);let c=FinitePathCategory::new(3,graph,64).unwrap();let lookup=PathLookup::new(c.paths());for (id,p) in c.paths().iter().enumerate(){assert_eq!(lookup.find(p.source(),p.edges()),Ok(id));}assert_eq!(lookup.find(0,&[999]),Err(PathError::MissingComposite));
 let first=c.edge_path(1).unwrap();let second=c.edge_path(0).unwrap();let composite=c.compose(first,second).unwrap().unwrap();assert_eq!(c.path(composite).unwrap().edges(),[1,0]);assert_ne!(c.edge_path(1),c.edge_path(3));assert_eq!(c.compose(first,2).unwrap(),None);assert_eq!(c.compose(0,first).unwrap(),Some(first));assert_eq!(c.compose(first,1).unwrap(),Some(first));
}
'''


def challenge(subject):
    return '\n#[cfg(test)]mod independent_path_tests{use super::*;use std::collections::BTreeMap;\n'+ORIGINAL+TESTS+'\n}\n'
